{"command": "python3 << 'EOF'
# Keygen Tune Composition
# Key: A minor (A, C, E, G)
# Tempo: 135 BPM, Speed: 6
# 6 Channels: Kick(4), HiHat(5), SubBass(6), Bass(3), Pulse(2), Lead(1)

# Note definitions (FT2 format: semitones from C-1)
# C=0, C#=1, D=2, D#=3, E=4, F=5, F#=6, G=7, G#=8, A=9, A#=10, B=11
# Octave offset: each octave is +12

def note(name, octave):
    """Convert note name to FT2 semitone value"""
    notes_map = {'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5, 'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11}
    return notes_map[name] + (octave + 1) * 12

# A minor scale: A, B, C, D, E, F, G
# Notes to use:
A4 = note('A', 3)   # 9 + 48 = 57
B4 = note('B', 3)   # 11 + 48 = 59
C5 = note('C', 4)   # 0 + 60 = 60
D5 = note('D', 4)   # 2 + 60 = 62
E5 = note('E', 4)   # 4 + 60 = 64
F5 = note('F', 4)   # 5 + 60 = 65
G5 = note('G', 4)   # 7 + 60 = 67

# Lower octave for bass
A2 = note('A', 1)
E3 = note('E', 2)
A3 = note('A', 2)

# Even lower for sub bass
A1 = note('A', 0)
E2 = note('E', 1)

# Pattern data structure
patterns = {p: {ch: [None]*64 for ch in range(6)} for p in range(8)}

# PATTERN 0: INTRO (drums + bass foundation)
# Kick drum pattern (channel 0)
for row in [0, 8, 16, 24, 32, 40, 48, 56]:
    patterns[0][0][row] = (57, 4, 60)  # C4 on kick drum (sets pitch), instrument 4

# Hi-hat pattern (channel 1) - steady eighths
for row in range(0, 64, 8):
    patterns[0][1][row] = (57, 5, 60)  # Instrument 5 (hi-hat)

# Sub bass (channel 2) - A1 held
for row in [0, 16, 32, 48]:
    patterns[0][2][row] = (A1, 6, 60)  # Instrument 6

# Bass (channel 3) - A minor pattern
patterns[0][3][0] = (A2, 3, 60)
patterns[0][3][16] = (A2, 3, 60)
patterns[0][3][32] = (A2, 3, 60)
patterns[0][3][48] = (A2, 3, 60)

# PATTERN 1: BUILD (drums pick up, melody enters quietly)
# Kick drum - steady quarter notes
for row in [0, 16, 32, 48]:
    patterns[1][0][row] = (57, 4, 60)

# Hi-hat - more frequent
for row in range(0, 64, 4):
    patterns[1][1][row] = (57, 5, 50)

# Sub bass (channel 2)
patterns[1][2][0] = (A1, 6, 60)
patterns[1][2][16] = (A1, 6, 60)
patterns[1][2][32] = (E2, 6, 60)
patterns[1][2][48] = (A1, 6, 60)

# Bass (channel 3)
for row in [0, 16, 32, 48]:
    patterns[1][3][row] = (A3, 3, 60)

# Pulse (channel 4) - intro melody (quiet)
patterns[1][4][8] = (E5, 2, 40)
patterns[1][4][24] = (D5, 2, 40)

# Lead (channel 5)
patterns[1][5][12] = (A4, 1, 40)

# PATTERN 2: MAIN LOOP A (full arrangement - the main hook)
# Kick drum - energetic pattern
for row in [0, 8, 16, 24, 32, 40, 48, 56]:
    patterns[2][0][row] = (57, 4, 60)

# Hi-hat - very active
for row in range(0, 64, 4):
    patterns[2][1][row] = (57, 5, 55)

# Sub bass (channel 2)
sub_bass_pattern = [A1, 0, 0, 0, E2, 0, 0, 0, A1, 0, 0, 0, E2, 0, 0, 0]
for i in range(4):
    for j, n in enumerate(sub_bass_pattern):
        if n:
            patterns[2][2][i*16 + j] = (n, 6, 60)

# Bass (channel 3) - A minor arpeggio feel
bass_pattern = [A3, 0, C5, 0, E3, 0, A3, 0, A3, 0, C5, 0, E3, 0, A3, 0]
for i in range(4):
    for j, n in enumerate(bass_pattern):
        if n:
            patterns[2][3][i*16 + j] = (n, 3, 60)

# Pulse (channel 4) - harmonic layer
pulse_melody = [E5, 0, E5, D5, E5, 0, 0, D5, C5, 0, D5, 0, E5, 0, D5, 0]
for i in range(4):
    for j, n in enumerate(pulse_melody):
        if n:
            patterns[2][4][i*16 + j] = (n, 2, 55)

# Lead (channel 5) - main melody
lead_melody = [A4, 0, B4, 0, C5, 0, D5, 0, E5, 0, 0, 0, D5, C5, B4, A4]
for i in range(4):
    for j, n in enumerate(lead_melody):
        if n:
            patterns[2][5][i*16 + j] = (n, 1, 60)

# PATTERN 3: MAIN LOOP B (variation - switch melody)
# Similar to pattern 2 but with different lead melody
# Drums stay the same
for row in [0, 8, 16, 24, 32, 40, 48, 56]:
    patterns[3][0][row] = (57, 4, 60)

for row in range(0, 64, 4):
    patterns[3][1][row] = (57, 5, 55)

# Sub bass and bass same as pattern 2
for i in range(4):
    for j, n in enumerate(sub_bass_pattern):
        if n:
            patterns[3][2][i*16 + j] = (n, 6, 60)

for i in range(4):
    for j, n in enumerate(bass_pattern):
        if n:
            patterns[3][3][i*16 + j] = (n, 3, 60)

# Pulse - different variation
pulse_melody_b = [G5, 0, A4, 0, G5, 0, 0, F5, E5, 0, D5, 0, E5, 0, C5, D5]
for i in range(4):
    for j, n in enumerate(pulse_melody_b):
        if n:
            patterns[3][4][i*16 + j] = (n, 2, 55)

# Lead - alternate melody
lead_melody_b = [E5, D5, C5, B4, A4, B4, C5, D5, E5, 0, D5, 0, C5, B4, A4, 0]
for i in range(4):
    for j, n in enumerate(lead_melody_b):
        if n:
            patterns[3][5][i*16 + j] = (n, 1, 60)

# PATTERN 4: BUILD UP / CHORUS EFFECT
# More energetic, double the lead
for row in [0, 4, 8, 12, 16, 20, 24, 28, 32, 36, 40, 44, 48, 52, 56, 60]:
    patterns[4][0][row] = (57, 4, 65)

for row in range(0, 64, 2):
    patterns[4][1][row] = (57, 5, 60)

# Sub bass
sub_bass_fast = [A1, E2, A1, E2, A1, E2, A1, E2]
for i in range(8):
    for j, n in enumerate(sub_bass_fast):
        if n:
            patterns[4][2][i*8 + j] = (n, 6, 65)

# Bass - faster movement
bass_fast = [A3, C5, E3, A3, A3, C5, E3, A3]
for i in range(8):
    for j, n in enumerate(bass_fast):
        if n:
            patterns[4][3][i*8 + j] = (n, 3, 65)

# Pulse - double notes
for i in range(8):
    for j, n in enumerate([E5, E5, D5, D5, E5, E5, C5, C5]):
        if n:
            patterns[4][4][i*8 + j] = (n, 2, 60)

# Lead - fast melody runs
lead_fast = [A4, B4, C5, D5, E5, D5, C5, B4]
for i in range(8):
    for j, n in enumerate(lead_fast):
        if n:
            patterns[4][5][i*8 + j] = (n, 1, 65)

# PATTERN 5: BRIDGE / BREAKDOWN (reduce texture, then build)
# First half: minimal (rows 0-31)
patterns[5][0][0] = (57, 4, 50)
patterns[5][0][16] = (57, 4, 50)
patterns[5][1][0] = (57, 5, 40)
patterns[5][1][16] = (57, 5, 40)
patterns[5][2][0] = (A1, 6, 50)
patterns[5][2][16] = (A1, 6, 50)
patterns[5][3][0] = (A2, 3, 50)
patterns[5][3][16] = (A2, 3, 50)
patterns[5][5][8] = (A4, 1, 50)
patterns[5][5][24] = (E5, 1, 50)

# Second half: build back up (rows 32-63)
for row in [32, 40, 48, 56]:
    patterns[5][0][row] = (57, 4, 60)
for row in range(32, 64, 8):
    patterns[5][1][row] = (57, 5, 55)
for row in [32, 48]:
    patterns[5][2][row] = (A1, 6, 60)
    patterns[5][3][row] = (A3, 3, 60)

# Lead builds in bridge
bridge_melody = [A4, B4, C5, D5, E5, D5, C5, B4]
for i in range(4):
    patterns[5][5][32 + i*8] = (bridge_melody[i*2], 1, 55)
    patterns[5][5][32 + i*8 + 4] = (bridge_melody[i*2+1], 1, 55)

# Patterns 6-7 are same as patterns 2-3 (main loop repeats)

import json

# Convert to calls for FT2
calls = []
for pattern_num in range(6):  # Only patterns 0-5 need composition
    for row in range(64):
        for channel in range(6):
            cell_data = patterns[pattern_num][channel][row]
            if cell_data is not None:
                note_val, instrument, volume = cell_data
                calls.append({
                    "name": "pattern_set_cell",
                    "arguments": {
                        "pattern": pattern_num,
                        "row": row,
                        "channel": channel,
                        "note": note_val,
                        "instrument": instrument,
                        "volume": volume
                    }
                })

with open('/workspace/compose_tune.json', 'w') as f:
    json.dump(calls, f)

print(f"Composition created with {len(calls)} note events")
print("Patterns 6 and 7 will reuse patterns 2 and 3 via order list")
EOF

ft2 batch /workspace/compose_tune.json
"}

